import {
  resolvePanoramaUrl,
  type SceneGraph,
  type SceneNode,
  type SceneTransitionKind,
} from './scene-graph';

/**
 * SceneNavigator — pure state machine that holds the user's position
 * in a tour's scene graph plus undo/redo history.
 *
 * The viewer app subscribes to `change` events and reacts by:
 *   1. asking the renderer to swap panoramas via `setPanorama(url)`,
 *   2. resetting the camera to the destination's `arrive*` orientation
 *      (or the scene's `defaultYawDeg/defaultPitchDeg` if absent),
 *   3. re-mounting the POI overlay + hotspot overlay for the new scene.
 *
 * Pure module — no DOM, no Three.js, no I/O.
 */

export interface SceneNavigatorChange {
  fromSceneId: string | null;
  toSceneId: string;
  variantId: string | undefined;
  panoramaUrl: string;
  arriveYawDeg: number;
  arrivePitchDeg: number;
  transition: SceneTransitionKind;
  /** "teleport" via a hotspot, "jump" via minimap, "back"/"forward" via history. */
  cause: 'mount' | 'teleport' | 'jump' | 'back' | 'forward' | 'variant';
}

export type SceneNavigatorListener = (change: SceneNavigatorChange) => void;

export interface SceneNavigatorArgs {
  graph: SceneGraph;
  /** Optional override of the starting scene; defaults to `graph.rootSceneId`. */
  initialSceneId?: string;
  /** Optional override of the starting variant. */
  initialVariantId?: string;
}

interface NavState {
  sceneId: string;
  variantId: string | undefined;
}

export class SceneNavigator {
  private readonly graph: SceneGraph;
  private readonly listeners = new Set<SceneNavigatorListener>();
  private current: NavState;
  private readonly history: NavState[] = [];
  private readonly future: NavState[] = [];
  private mounted = false;

  constructor(args: SceneNavigatorArgs) {
    this.graph = args.graph;
    const startId = args.initialSceneId ?? args.graph.rootSceneId;
    if (!args.graph.scenes.has(startId)) {
      throw new Error(`SceneNavigator: initial scene "${startId}" not in graph`);
    }
    this.current = { sceneId: startId, variantId: args.initialVariantId };
  }

  get currentSceneId(): string {
    return this.current.sceneId;
  }

  get currentVariantId(): string | undefined {
    return this.current.variantId;
  }

  getCurrentScene(): SceneNode {
    return this.graph.scenes.get(this.current.sceneId)!;
  }

  canGoBack(): boolean {
    return this.history.length > 0;
  }

  canGoForward(): boolean {
    return this.future.length > 0;
  }

  subscribe(listener: SceneNavigatorListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  /**
   * Emit the initial scene change. Call once after the renderer is ready so
   * the very first scene comes through the same code path as teleports.
   */
  mount(): void {
    if (this.mounted) return;
    this.mounted = true;
    this.emit(null, 'mount');
  }

  /**
   * Move to the destination of a hotspot. The hotspot must exist on the current scene
   * (caller is responsible for the lookup — this method just takes the destination spec).
   */
  teleport(hotspotTo: {
    toSceneId: string;
    arriveYawDeg?: number;
    arrivePitchDeg?: number;
    transition?: SceneTransitionKind;
  }): void {
    this.advanceTo(
      { sceneId: hotspotTo.toSceneId, variantId: undefined },
      'teleport',
      hotspotTo.arriveYawDeg,
      hotspotTo.arrivePitchDeg,
      hotspotTo.transition,
    );
  }

  /** Jump to any scene without going through a hotspot (e.g. minimap click). */
  jumpTo(sceneId: string, transition: SceneTransitionKind = 'fade'): void {
    this.advanceTo({ sceneId, variantId: undefined }, 'jump', undefined, undefined, transition);
  }

  back(): void {
    const previous = this.history.pop();
    if (previous === undefined) return;
    this.future.push(this.current);
    this.current = previous;
    this.emit(null, 'back');
  }

  forward(): void {
    const next = this.future.pop();
    if (next === undefined) return;
    this.history.push(this.current);
    this.current = next;
    this.emit(null, 'forward');
  }

  setVariant(variantId: string | undefined): void {
    if (variantId === this.current.variantId) return;
    // Variant changes don't push history — they're a sub-state of the current scene.
    this.current = { ...this.current, variantId };
    this.emit(null, 'variant');
  }

  private advanceTo(
    next: NavState,
    cause: SceneNavigatorChange['cause'],
    arriveYaw?: number,
    arrivePitch?: number,
    transition?: SceneTransitionKind,
  ): void {
    if (!this.graph.scenes.has(next.sceneId)) {
      throw new Error(`SceneNavigator: scene "${next.sceneId}" not in graph`);
    }
    if (next.sceneId === this.current.sceneId && next.variantId === this.current.variantId) {
      return;
    }
    this.history.push(this.current);
    this.future.length = 0;
    this.current = next;
    this.emit(null, cause, arriveYaw, arrivePitch, transition);
  }

  private emit(
    _previous: NavState | null,
    cause: SceneNavigatorChange['cause'],
    arriveYaw?: number,
    arrivePitch?: number,
    transition?: SceneTransitionKind,
  ): void {
    const scene = this.getCurrentScene();
    const previousSceneId =
      cause === 'mount' ? null : (this.history[this.history.length - 1]?.sceneId ?? null);

    const change: SceneNavigatorChange = {
      fromSceneId: previousSceneId,
      toSceneId: scene.id,
      variantId: this.current.variantId,
      panoramaUrl: resolvePanoramaUrl(scene, this.current.variantId),
      arriveYawDeg: arriveYaw ?? scene.defaultYawDeg,
      arrivePitchDeg: arrivePitch ?? scene.defaultPitchDeg,
      transition: transition ?? (cause === 'mount' ? 'instant' : 'fade'),
      cause,
    };
    for (const listener of this.listeners) listener(change);
  }
}
