import type { CameraState } from '@nova/viewer-core';

/**
 * Light-control bar — a clean, always-visible panel of toggles for an
 * interactive night scene. Each chip flips a real, pre-rendered additive
 * light layer (a room's lights, the pool lights …) on/off in the renderer,
 * so tapping it turns that area's actual Cycles-rendered lights on or off.
 *
 * Anchored, camera-projected markers proved fragile (often off-screen behind
 * the viewer) and cluttered the scene, so the switches live in a single
 * bottom-centre bar that is always reachable.
 */

export interface LightSwitch {
  /** Matches the renderer layer id. */
  id: string;
  label: string;
  /** Whether the light starts on (layer visible). */
  on: boolean;
  /** Optional glyph (defaults to a bulb). */
  glyph?: string;
}

export interface LightSwitchOverlayArgs {
  hostEl: HTMLElement;
  switches: readonly LightSwitch[];
  /** Kept for API symmetry with the other overlays (unused — the bar is
   *  screen-anchored, not world-anchored). */
  initialCamera?: CameraState;
  onToggle: (id: string, on: boolean) => void;
}

export interface LightSwitchOverlayHandle {
  /** No-op: the bar is screen-anchored, not camera-projected. */
  update(camera: CameraState): void;
  dispose(): void;
}

function injectStyles(): void {
  if (typeof document === 'undefined' || document.getElementById('viewer-lightbar-style')) return;
  const s = document.createElement('style');
  s.id = 'viewer-lightbar-style';
  s.textContent = `
.viewer-lightbar{position:absolute;left:50%;bottom:calc(74px + env(safe-area-inset-bottom));
  transform:translateX(-50%);z-index:40;display:flex;align-items:center;gap:8px;max-width:94vw;
  padding:8px 10px 8px 14px;border-radius:18px;border:1px solid rgba(255,255,255,.14);
  background:rgba(12,16,24,.62);backdrop-filter:blur(12px);box-shadow:0 10px 34px rgba(0,0,0,.5);
  overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.viewer-lightbar::-webkit-scrollbar{display:none}
.viewer-lightbar-title{flex:0 0 auto;display:flex;align-items:center;gap:6px;font:700 12px/1 system-ui,
  -apple-system,Segoe UI,sans-serif;color:#e8edf6;opacity:.9;padding-right:2px}
.viewer-lightbar-chip{flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;cursor:pointer;
  padding:9px 13px;border-radius:999px;border:1px solid rgba(255,255,255,.22);white-space:nowrap;
  font:600 12.5px/1 system-ui,-apple-system,Segoe UI,sans-serif;color:#dbe3ef;
  background:rgba(255,255,255,.06);transition:background .18s ease,box-shadow .18s ease,
  color .18s ease,border-color .18s ease,transform .1s ease}
.viewer-lightbar-chip:active{transform:scale(.95)}
.viewer-lightbar-chip .g{font-size:14px;filter:grayscale(1) brightness(1.7);opacity:.65}
.viewer-lightbar-chip.is-on{background:linear-gradient(135deg,#fde68a,#facc15);color:#3a2c02;
  border-color:#fcd34d;box-shadow:0 0 16px rgba(250,204,21,.6)}
.viewer-lightbar-chip.is-on .g{filter:none;opacity:1}
`;
  document.head.append(s);
}

export const mountLightSwitchOverlay = (args: LightSwitchOverlayArgs): LightSwitchOverlayHandle => {
  injectStyles();
  const bar = document.createElement('div');
  bar.className = 'viewer-lightbar';
  bar.setAttribute('data-testid', 'lightswitch-overlay');
  bar.setAttribute('role', 'group');
  bar.setAttribute('aria-label', 'Room lights');

  const title = document.createElement('span');
  title.className = 'viewer-lightbar-title';
  title.innerHTML = '<span aria-hidden="true">💡</span><span>Lights</span>';
  bar.append(title);

  const state = new Map<string, boolean>();
  for (const sw of args.switches) {
    state.set(sw.id, sw.on);
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'viewer-lightbar-chip';
    const paint = (): void => {
      const on = state.get(sw.id) ?? sw.on;
      chip.classList.toggle('is-on', on);
      chip.setAttribute('aria-pressed', on ? 'true' : 'false');
      chip.setAttribute('aria-label', `${sw.label} lights: turn ${on ? 'off' : 'on'}`);
      chip.innerHTML = `<span class="g" aria-hidden="true">${sw.glyph ?? '💡'}</span>${sw.label}`;
    };
    chip.addEventListener('click', (e) => {
      e.preventDefault();
      const next = !(state.get(sw.id) ?? sw.on);
      state.set(sw.id, next);
      paint();
      args.onToggle(sw.id, next);
    });
    paint();
    bar.append(chip);
  }

  args.hostEl.append(bar);

  return {
    update(): void {
      /* screen-anchored — nothing to reposition */
    },
    dispose(): void {
      if (bar.parentElement === args.hostEl) args.hostEl.removeChild(bar);
    },
  };
};
