/**
 * Day/night controller — pure logic, no Three.js.
 *
 * The viewer adapter binds the output values to:
 *   • `scene.environment` intensity (envIntensity 0..1)
 *   • sun directional light direction (sunDir, normalised)
 *   • sky colour (skyTopRgb / skyHorizonRgb), e.g. for a gradient sphere
 *   • ambient fog colour (fogRgb)
 *   • optional star sprite opacity (starsOpacity 0..1)
 *
 * Input: a normalised `cyclePosition` in [0..1) where
 *   0.00 = midnight
 *   0.25 = sunrise
 *   0.50 = noon
 *   0.75 = sunset
 *
 * Two driving modes:
 *   - `manual` — caller sets cyclePosition directly (slider, button toggle)
 *   - `autoSpeed` — caller sets a multiplier (1 = real-time, 60 = 1 min/sec)
 *
 * The day/night module is GPU-free + framework-free so tests run in a
 * Node process without WebGL. The viewer's fx-runtime owns the call to
 * `tick(dtMs)` each frame.
 */

export interface DayNightConfig {
  /** Starting cycle position 0..1. Default 0.5 (noon). */
  readonly initialCyclePosition?: number;
  /** Multiplier when in autoSpeed mode (cycles per real second). 1.0 = real-time at 24h/day. */
  readonly autoSpeedCyclesPerSec?: number;
}

export interface DayNightFrame {
  /** Where in the day/night cycle we are (0..1). */
  readonly cyclePosition: number;
  /** Sun direction (normalised vec3). At dawn/dusk, sun is on the horizon. */
  readonly sunDir: readonly [number, number, number];
  /** Environment intensity 0..1 — drives `scene.environment` blend. */
  readonly envIntensity: number;
  /** Sky top colour (top of the dome) — linear RGB. */
  readonly skyTopRgb: readonly [number, number, number];
  /** Sky horizon colour — linear RGB. */
  readonly skyHorizonRgb: readonly [number, number, number];
  /** Fog/ambient colour. */
  readonly fogRgb: readonly [number, number, number];
  /** 0 (no stars) ↔ 1 (full stars). */
  readonly starsOpacity: number;
  /** Convenience label for the UI. */
  readonly phase: 'night' | 'dawn' | 'day' | 'dusk';
}

export class DayNightController {
  private cyclePosition: number;
  private mode: 'manual' | 'auto' = 'manual';
  private autoSpeed: number;

  constructor(cfg: DayNightConfig = {}) {
    this.cyclePosition = normaliseCycle(cfg.initialCyclePosition ?? 0.5);
    this.autoSpeed = cfg.autoSpeedCyclesPerSec ?? 1 / 60; // default: 1 cycle / minute
  }

  setManual(cyclePosition: number): void {
    this.mode = 'manual';
    this.cyclePosition = normaliseCycle(cyclePosition);
  }

  setAuto(autoSpeedCyclesPerSec?: number): void {
    this.mode = 'auto';
    if (autoSpeedCyclesPerSec !== undefined) this.autoSpeed = autoSpeedCyclesPerSec;
  }

  /** Snap to one of the four named phases. */
  setPhase(phase: 'night' | 'dawn' | 'day' | 'dusk'): void {
    this.mode = 'manual';
    this.cyclePosition = phaseAnchorPosition(phase);
  }

  /** Toggle between day and night anchors. */
  toggleDayNight(): void {
    this.mode = 'manual';
    const isDayish = this.cyclePosition >= 0.25 && this.cyclePosition < 0.75;
    this.cyclePosition = isDayish ? 0 : 0.5;
  }

  /** Advance the cycle in auto-mode; no-op in manual. */
  tick(dtMs: number): void {
    if (this.mode !== 'auto') return;
    const dtS = dtMs / 1000;
    this.cyclePosition = normaliseCycle(this.cyclePosition + this.autoSpeed * dtS);
  }

  /** Sample every output. */
  frame(): DayNightFrame {
    return sampleFrame(this.cyclePosition);
  }
}

// ── pure samplers ────────────────────────────────────────────────────────

const NIGHT_TOP: readonly [number, number, number] = [0.02, 0.04, 0.12];
const NIGHT_HORIZON: readonly [number, number, number] = [0.05, 0.08, 0.18];
const DAWN_TOP: readonly [number, number, number] = [0.35, 0.45, 0.7];
const DAWN_HORIZON: readonly [number, number, number] = [0.95, 0.55, 0.35];
const DAY_TOP: readonly [number, number, number] = [0.4, 0.6, 0.95];
const DAY_HORIZON: readonly [number, number, number] = [0.75, 0.85, 0.95];
const DUSK_TOP: readonly [number, number, number] = [0.3, 0.2, 0.45];
const DUSK_HORIZON: readonly [number, number, number] = [0.95, 0.45, 0.25];

export function sampleFrame(cyclePosition: number): DayNightFrame {
  const t = normaliseCycle(cyclePosition);
  // 4 anchor positions:
  //   0.00 night    0.25 dawn    0.50 day    0.75 dusk
  let phase: DayNightFrame['phase'];
  let topRgb: readonly [number, number, number];
  let horizonRgb: readonly [number, number, number];
  let envIntensity: number;
  let starsOpacity: number;
  if (t < 0.25) {
    // night → dawn
    const k = t / 0.25;
    phase = k < 0.5 ? 'night' : 'dawn';
    topRgb = lerpRgb(NIGHT_TOP, DAWN_TOP, k);
    horizonRgb = lerpRgb(NIGHT_HORIZON, DAWN_HORIZON, k);
    envIntensity = lerp(0.05, 0.55, k);
    starsOpacity = lerp(1, 0, k);
  } else if (t < 0.5) {
    // dawn → day
    const k = (t - 0.25) / 0.25;
    phase = k < 0.5 ? 'dawn' : 'day';
    topRgb = lerpRgb(DAWN_TOP, DAY_TOP, k);
    horizonRgb = lerpRgb(DAWN_HORIZON, DAY_HORIZON, k);
    envIntensity = lerp(0.55, 1.0, k);
    starsOpacity = 0;
  } else if (t < 0.75) {
    // day → dusk
    const k = (t - 0.5) / 0.25;
    phase = k < 0.5 ? 'day' : 'dusk';
    topRgb = lerpRgb(DAY_TOP, DUSK_TOP, k);
    horizonRgb = lerpRgb(DAY_HORIZON, DUSK_HORIZON, k);
    envIntensity = lerp(1.0, 0.45, k);
    starsOpacity = 0;
  } else {
    // dusk → night
    const k = (t - 0.75) / 0.25;
    phase = k < 0.5 ? 'dusk' : 'night';
    topRgb = lerpRgb(DUSK_TOP, NIGHT_TOP, k);
    horizonRgb = lerpRgb(DUSK_HORIZON, NIGHT_HORIZON, k);
    envIntensity = lerp(0.45, 0.05, k);
    starsOpacity = lerp(0, 1, k);
  }
  const sunAngleRad = (t - 0.25) * Math.PI * 2; // sun above horizon between 0.25 and 0.75
  const sunDir: readonly [number, number, number] = [
    Math.cos(sunAngleRad),
    Math.sin(sunAngleRad),
    0,
  ];
  // fog blends top + horizon ~50/50
  const fogRgb: readonly [number, number, number] = [
    (topRgb[0] + horizonRgb[0]) / 2,
    (topRgb[1] + horizonRgb[1]) / 2,
    (topRgb[2] + horizonRgb[2]) / 2,
  ];
  return {
    cyclePosition: t,
    sunDir,
    envIntensity,
    skyTopRgb: topRgb,
    skyHorizonRgb: horizonRgb,
    fogRgb,
    starsOpacity,
    phase,
  };
}

function normaliseCycle(t: number): number {
  if (!Number.isFinite(t)) return 0;
  const wrapped = t - Math.floor(t);
  return wrapped < 0 ? wrapped + 1 : wrapped;
}

function lerp(a: number, b: number, k: number): number {
  return a + (b - a) * Math.max(0, Math.min(1, k));
}

function lerpRgb(
  a: readonly [number, number, number],
  b: readonly [number, number, number],
  k: number,
): readonly [number, number, number] {
  return [lerp(a[0], b[0], k), lerp(a[1], b[1], k), lerp(a[2], b[2], k)];
}

function phaseAnchorPosition(phase: 'night' | 'dawn' | 'day' | 'dusk'): number {
  switch (phase) {
    case 'night':
      return 0;
    case 'dawn':
      return 0.25;
    case 'day':
      return 0.5;
    case 'dusk':
      return 0.75;
  }
}
