/**
 * The canonical *guided* route through the villa — a single ordered walk so the
 * tour reads as one connected experience: you start outside at the pool, move
 * around the grounds, then enter and go room-by-room. The tour stepper (Next /
 * Prev / Auto-pilot) and the floor-plan route line both follow this order.
 * (Intermediate capture points like the garden corner / stair landings get
 * spliced in here as they're rendered.)
 */
export const VILLA_TOUR_SEQUENCE: readonly string[] = [
  'exterior', // Pool & Garden — arrival
  'exterior_corner', // Garden Corner — walk the grounds
  'exterior2', // Terrace
  'exterior3', // Side Path
  'kitchen', // …enter: Kitchen & Dining
  'kit-living', // walk into the living area
  'kit-dining', // …and the dining table
  'bedroom', // up to the Bedroom & Lounge
  'suite', // Master Suite
];

// ── Interactive night lighting (real, per-room toggles) ───────────────
// At night, a scene can be lit by compositing pre-rendered Cycles light
// LAYERS: `baseUrl` is the room with every artificial light OFF (moonlit),
// and each `layers[]` entry is one room's lights baked on black. The viewer
// adds them additively and a clickable switch toggles each — so tapping a
// switch turns that room's REAL rendered lights on/off. Photoreal + mobile.
export interface VillaInteractiveLayer {
  id: string;
  url: string;
}
export interface VillaInteractiveSwitch {
  id: string; // matches a layer id
  label: string;
  glyph?: string;
}
export interface VillaInteractiveScene {
  baseUrl: string;
  layers: VillaInteractiveLayer[];
  switches: VillaInteractiveSwitch[];
}

