import type { MinimapAnchor, SceneNode } from './scene-graph';

/**
 * Minimap projection — pure helpers for the top-down view (F-15).
 *
 * Scenes have `minimapAnchor: {x,y}` in 0..1 normalised floor-plan space.
 * This module maps those to pixel coordinates within a viewBox, computes the
 * FOV wedge for the current camera, and supports hit-testing for click-to-jump.
 *
 * No DOM, no Three.js — output is plain numbers for the SVG layer to consume.
 */

export interface MinimapViewBox {
  widthPx: number;
  heightPx: number;
}

export const DEFAULT_MINIMAP_VIEW_BOX: MinimapViewBox = { widthPx: 200, heightPx: 200 };

export interface MinimapPoint {
  sceneId: string;
  xPx: number;
  yPx: number;
  radiusPx: number;
}

export interface MinimapFovWedge {
  /** Centre of the wedge — the camera origin (which is the current scene anchor). */
  centreXPx: number;
  centreYPx: number;
  /** Direction the camera is looking, degrees clockwise from "up" (north). */
  bearingDeg: number;
  /** Half-angle of the wedge in degrees (half of the camera horizontal FOV). */
  halfFovDeg: number;
  /** Length of the wedge in pixels — caller decides visual radius (e.g. 40px). */
  reachPx: number;
}

const DEFAULT_RADIUS_PX = 8;
const DEFAULT_REACH_PX = 40;

const clamp01 = (n: number): number => (n < 0 ? 0 : n > 1 ? 1 : n);

export const projectSceneToMinimap = (
  anchor: MinimapAnchor,
  viewBox: MinimapViewBox = DEFAULT_MINIMAP_VIEW_BOX,
): { xPx: number; yPx: number; radiusPx: number } => ({
  xPx: clamp01(anchor.x) * viewBox.widthPx,
  yPx: clamp01(anchor.y) * viewBox.heightPx,
  radiusPx: anchor.radiusPx ?? DEFAULT_RADIUS_PX,
});

export const projectScenesToMinimap = (
  scenes: readonly SceneNode[],
  viewBox: MinimapViewBox = DEFAULT_MINIMAP_VIEW_BOX,
): readonly MinimapPoint[] => {
  const out: MinimapPoint[] = [];
  for (const scene of scenes) {
    if (scene.minimapAnchor === undefined) continue;
    const { xPx, yPx, radiusPx } = projectSceneToMinimap(scene.minimapAnchor, viewBox);
    out.push({ sceneId: scene.id, xPx, yPx, radiusPx });
  }
  return out;
};

export const projectFovWedge = (args: {
  scene: SceneNode;
  cameraYawDeg: number;
  cameraFovDeg: number;
  viewBox?: MinimapViewBox;
  reachPx?: number;
}): MinimapFovWedge | null => {
  if (args.scene.minimapAnchor === undefined) return null;
  const viewBox = args.viewBox ?? DEFAULT_MINIMAP_VIEW_BOX;
  const { xPx, yPx } = projectSceneToMinimap(args.scene.minimapAnchor, viewBox);
  // Convention: in panorama coordinates, yaw=0 looks "north" (forward) and increases clockwise.
  // The minimap uses "up = north", so the bearing is the yaw mod 360.
  const bearingDeg = ((args.cameraYawDeg % 360) + 360) % 360;
  return {
    centreXPx: xPx,
    centreYPx: yPx,
    bearingDeg,
    halfFovDeg: args.cameraFovDeg / 2,
    reachPx: args.reachPx ?? DEFAULT_REACH_PX,
  };
};

/** SVG path "d" string for the FOV wedge — a triangle/arc from centre. */
export const fovWedgePath = (wedge: MinimapFovWedge): string => {
  const toRad = (d: number): number => (d * Math.PI) / 180;
  // Compute the two outer corner points of the wedge.
  // Bearing 0 points "up" (–y in SVG coords). Add 90° to convert from "up" reference to "right" reference.
  const baseRad = toRad(wedge.bearingDeg - 90);
  const leftRad = baseRad - toRad(wedge.halfFovDeg);
  const rightRad = baseRad + toRad(wedge.halfFovDeg);
  const leftX = wedge.centreXPx + wedge.reachPx * Math.cos(leftRad);
  const leftY = wedge.centreYPx + wedge.reachPx * Math.sin(leftRad);
  const rightX = wedge.centreXPx + wedge.reachPx * Math.cos(rightRad);
  const rightY = wedge.centreYPx + wedge.reachPx * Math.sin(rightRad);
  // Triangle from centre → leftPoint → rightPoint → centre.
  return `M ${wedge.centreXPx.toFixed(2)} ${wedge.centreYPx.toFixed(2)} L ${leftX.toFixed(2)} ${leftY.toFixed(2)} L ${rightX.toFixed(2)} ${rightY.toFixed(2)} Z`;
};

export const pickNearestScene = (args: {
  pointXPx: number;
  pointYPx: number;
  scenes: readonly MinimapPoint[];
  thresholdPx?: number;
}): string | null => {
  const threshold = args.thresholdPx ?? 16;
  let bestId: string | null = null;
  let bestDistSq = threshold * threshold;
  for (const scene of args.scenes) {
    const dx = scene.xPx - args.pointXPx;
    const dy = scene.yPx - args.pointYPx;
    const distSq = dx * dx + dy * dy;
    if (distSq <= bestDistSq) {
      bestDistSq = distSq;
      bestId = scene.sceneId;
    }
  }
  return bestId;
};
