/**
 * F-22 weather FX — rain, snow, fog (volumetric haze parameter pack).
 *
 * Rain + snow are emitters that spawn particles above the camera + let
 * gravity pull them down. Fog is NOT a particle effect — it's a uniform
 * pack the renderer feeds to a depth-fade shader.
 *
 * Note: "above camera" is a renderer concern (the emitter takes a
 * dynamic `cameraPosition` setter so it can keep the spawn region
 * anchored as the user moves).
 */

import { SeededRng } from './rng';

import type { Emitter, Rgba, SpawnSpec, Vec3 } from './types';

// ── Rain ────────────────────────────────────────────────────────────────────

export interface RainConfig {
  cameraPosition: Vec3;
  /** Particles emitted per second. */
  ratePerSec: number;
  /** Width of the spawn cube (centred on camera, XZ). */
  spawnWidthM: number;
  /** How far above the camera particles spawn. */
  spawnHeightAboveM: number;
  /** Initial downward velocity (m/s). */
  fallSpeedMs: number;
  /** Lifetime per drop (seconds). */
  lifeS: number;
  seed: number;
}

export class RainEmitter implements Emitter {
  readonly id: string;
  private cameraPosition: Vec3;
  private readonly cfg: RainConfig;
  private readonly rng: SeededRng;
  private accumS = 0;
  private stopped = false;

  constructor(id: string, cfg: RainConfig) {
    this.id = id;
    this.cfg = cfg;
    this.cameraPosition = cfg.cameraPosition;
    this.rng = new SeededRng(cfg.seed);
  }

  setCameraPosition(next: Vec3): void {
    this.cameraPosition = next;
  }

  stop(): void {
    this.stopped = true;
  }

  emit(dtS: number, _now: number): readonly SpawnSpec[] {
    void _now;
    if (this.stopped) return [];
    this.accumS += dtS * this.cfg.ratePerSec;
    const count = Math.floor(this.accumS);
    this.accumS -= count;
    const out: SpawnSpec[] = [];
    for (let i = 0; i < count; i++) {
      out.push({
        position: [
          this.cameraPosition[0] +
            this.rng.range(-this.cfg.spawnWidthM / 2, this.cfg.spawnWidthM / 2),
          this.cameraPosition[1] + this.cfg.spawnHeightAboveM,
          this.cameraPosition[2] +
            this.rng.range(-this.cfg.spawnWidthM / 2, this.cfg.spawnWidthM / 2),
        ],
        velocity: [0, -this.cfg.fallSpeedMs, 0],
        lifeS: this.cfg.lifeS,
        size: 0.02,
        color: [0.7, 0.85, 1.0, 0.6],
        kind: 'fx:rain',
      });
    }
    return out;
  }

  done(): boolean {
    return this.stopped;
  }
}

// ── Snow ────────────────────────────────────────────────────────────────────

export interface SnowConfig {
  cameraPosition: Vec3;
  ratePerSec: number;
  spawnWidthM: number;
  spawnHeightAboveM: number;
  /** Initial downward velocity (m/s). Snow falls slower than rain. */
  fallSpeedMs: number;
  /** Horizontal drift speed (m/s, sinusoidal wobble). */
  driftMs: number;
  lifeS: number;
  seed: number;
}

export class SnowEmitter implements Emitter {
  readonly id: string;
  private cameraPosition: Vec3;
  private readonly cfg: SnowConfig;
  private readonly rng: SeededRng;
  private accumS = 0;
  private stopped = false;

  constructor(id: string, cfg: SnowConfig) {
    this.id = id;
    this.cfg = cfg;
    this.cameraPosition = cfg.cameraPosition;
    this.rng = new SeededRng(cfg.seed);
  }

  setCameraPosition(next: Vec3): void {
    this.cameraPosition = next;
  }

  stop(): void {
    this.stopped = true;
  }

  emit(dtS: number, _now: number): readonly SpawnSpec[] {
    void _now;
    if (this.stopped) return [];
    this.accumS += dtS * this.cfg.ratePerSec;
    const count = Math.floor(this.accumS);
    this.accumS -= count;
    const out: SpawnSpec[] = [];
    for (let i = 0; i < count; i++) {
      out.push({
        position: [
          this.cameraPosition[0] +
            this.rng.range(-this.cfg.spawnWidthM / 2, this.cfg.spawnWidthM / 2),
          this.cameraPosition[1] + this.cfg.spawnHeightAboveM,
          this.cameraPosition[2] +
            this.rng.range(-this.cfg.spawnWidthM / 2, this.cfg.spawnWidthM / 2),
        ],
        velocity: [
          this.rng.range(-this.cfg.driftMs, this.cfg.driftMs),
          -this.cfg.fallSpeedMs * this.rng.range(0.7, 1.0),
          this.rng.range(-this.cfg.driftMs, this.cfg.driftMs),
        ],
        lifeS: this.cfg.lifeS,
        size: 0.04,
        color: [1.0, 1.0, 1.0, 0.9],
        kind: 'fx:snow',
      });
    }
    return out;
  }

  done(): boolean {
    return this.stopped;
  }
}

// ── Fog ─────────────────────────────────────────────────────────────────────

export type FogKind = 'none' | 'light-mist' | 'haze' | 'thick-fog';

export interface FogProfile {
  kind: FogKind;
  /** Linear fog `near` plane (metres). */
  nearM: number;
  /** Linear fog `far` plane (metres). */
  farM: number;
  /** Fog colour applied at full density. */
  color: Rgba;
}

export const FOG_PROFILES: Readonly<Record<FogKind, FogProfile>> = {
  none: { kind: 'none', nearM: 0, farM: 0, color: [0, 0, 0, 0] },
  'light-mist': {
    kind: 'light-mist',
    nearM: 20,
    farM: 120,
    color: [0.86, 0.9, 0.95, 0.3],
  },
  haze: {
    kind: 'haze',
    nearM: 10,
    farM: 60,
    color: [0.85, 0.85, 0.85, 0.5],
  },
  'thick-fog': {
    kind: 'thick-fog',
    nearM: 2,
    farM: 25,
    color: [0.78, 0.82, 0.84, 0.85],
  },
};

/** Pick a fog profile by kind. Defaults to "none" if the lookup misses. */
export function selectFogProfile(kind: FogKind): FogProfile {
  return FOG_PROFILES[kind] ?? FOG_PROFILES.none;
}
