/**
 * Scene-wide chip row for the real-photo tour: day/night, weather,
 * doorbell. These are global effects (not anchored to a twin) so they
 * sit above the per-twin chip row from `procedural-chip-overlay`.
 *
 * Day/night + weather are capability-gated against the tenant's
 * `TenantInteractionCapabilities.effects.*` flags; doorbell is a
 * universal courtesy chime that just calls into `tour-effects`.
 */
import type { TenantInteractionCapabilities } from '@nova/digital-twin';
import type { TourEffectsHandle } from './tour-effects';

export interface SceneEffectsChipsArgs {
  readonly hostEl: HTMLElement;
  readonly effects: TourEffectsHandle;
  readonly capabilities: TenantInteractionCapabilities;
}

export interface SceneEffectsChipsHandle {
  dispose(): void;
}

export function mountSceneEffectsChips(args: SceneEffectsChipsArgs): SceneEffectsChipsHandle {
  const root = document.createElement('div');
  root.className = 'nova-scene-effects-chips';
  root.style.cssText = `
    position: absolute;
    inset-inline: 0;
    bottom: 88px;
    padding: 8px 20px 0 20px;
    z-index: 51;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    pointer-events: none;
  `;
  args.hostEl.appendChild(root);

  function makeChip(initialLabel: string, onClick: (btn: HTMLButtonElement) => void): void {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = initialLabel;
    btn.style.cssText = `
      pointer-events: auto;
      min-height: 40px;
      padding: 8px 16px;
      border-radius: 22px;
      border: 1px solid rgba(255, 255, 255, 0.22);
      background: linear-gradient(135deg, rgba(15, 23, 42, 0.88), rgba(30, 41, 59, 0.88));
      color: #f8fafc;
      font: 600 13px/1.2 system-ui, -apple-system, Segoe UI, sans-serif;
      cursor: pointer;
      backdrop-filter: blur(8px);
      box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
      transition:
        transform 160ms ease,
        background 220ms ease;
    `;
    btn.addEventListener('mouseenter', () => {
      btn.style.transform = 'translateY(-2px)';
    });
    btn.addEventListener('mouseleave', () => {
      btn.style.transform = '';
    });
    btn.addEventListener('click', () => onClick(btn));
    root.appendChild(btn);
  }

  if (args.capabilities.effects?.dayNight === true) {
    makeChip('🌙 Switch to night', (btn) => {
      const next = !args.effects.isDayNightOn();
      args.effects.setDayNight(next);
      btn.textContent = next ? '☀ Switch to day' : '🌙 Switch to night';
      btn.style.background = next
        ? 'linear-gradient(135deg, rgba(30, 27, 75, 0.9), rgba(67, 56, 202, 0.9))'
        : 'linear-gradient(135deg, rgba(15, 23, 42, 0.88), rgba(30, 41, 59, 0.88))';
    });
  }

  if (args.capabilities.effects?.weather === true) {
    makeChip('🌧 Start rain', (btn) => {
      const next = !args.effects.isWeatherOn();
      args.effects.setWeather(next);
      btn.textContent = next ? '☀ Stop rain' : '🌧 Start rain';
      btn.style.background = next
        ? 'linear-gradient(135deg, rgba(15, 76, 117, 0.9), rgba(37, 99, 235, 0.9))'
        : 'linear-gradient(135deg, rgba(15, 23, 42, 0.88), rgba(30, 41, 59, 0.88))';
    });
  }

  makeChip('🔔 Ring doorbell', () => {
    args.effects.ringDoorbell();
  });

  return {
    dispose(): void {
      root.remove();
    },
  };
}
