/**
 * Viewer state machine. The renderer maintains exactly one of these states
 * at a time and surfaces transitions via `subscribe(listener)`. UI chrome
 * (loading overlay, error screen, compass) reads state to decide what to
 * paint without coupling to the renderer internals.
 *
 * Transitions:
 *   INITIALIZING → CAPABILITY_OK → LOADING_PANORAMA → READY ↔ NAVIGATING → READY
 *                                                              ↘ ERROR
 *   any → ERROR (terminal)
 *   any except ERROR → CAPABILITY_FAILED (when WebGPU + WebGL2 both absent)
 *
 * The machine is intentionally tiny — Three.js is the render loop; this
 * just gates which UI fragment is visible + which events the host should
 * forward to the renderer.
 */

export type ViewerState =
  | { kind: 'INITIALIZING' }
  | { kind: 'CAPABILITY_OK'; backend: 'webgpu' | 'webgl2' }
  | { kind: 'CAPABILITY_FAILED'; reason: string }
  | { kind: 'LOADING_PANORAMA'; sceneId: string; progress01: number }
  | { kind: 'READY'; sceneId: string }
  | { kind: 'NAVIGATING'; fromSceneId: string; toSceneId: string; progress01: number }
  | { kind: 'ERROR'; code: string; message: string };

export type ViewerEvent =
  | { kind: 'capability_resolved'; backend: 'webgpu' | 'webgl2' }
  | { kind: 'capability_failed'; reason: string }
  | { kind: 'load_started'; sceneId: string }
  | { kind: 'load_progress'; sceneId: string; progress01: number }
  | { kind: 'load_completed'; sceneId: string }
  | { kind: 'navigation_started'; fromSceneId: string; toSceneId: string }
  | { kind: 'navigation_progress'; fromSceneId: string; toSceneId: string; progress01: number }
  | { kind: 'navigation_completed'; sceneId: string }
  | { kind: 'fatal_error'; code: string; message: string };

type Listener = (state: ViewerState) => void;

export class ViewerStateMachine {
  private current: ViewerState = { kind: 'INITIALIZING' };
  private readonly listeners = new Set<Listener>();

  getState(): ViewerState {
    return this.current;
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    listener(this.current);
    return () => this.listeners.delete(listener);
  }

  /**
   * Apply an event. Invalid transitions are no-ops (event silently dropped)
   * EXCEPT for `fatal_error` which is always honoured.
   */
  dispatch(event: ViewerEvent): void {
    const next = nextState(this.current, event);
    if (next === null) return;
    this.current = next;
    for (const l of this.listeners) l(this.current);
  }
}

const nextState = (state: ViewerState, event: ViewerEvent): ViewerState | null => {
  if (event.kind === 'fatal_error') {
    if (state.kind === 'ERROR') return null;
    return { kind: 'ERROR', code: event.code, message: event.message };
  }
  if (state.kind === 'ERROR' || state.kind === 'CAPABILITY_FAILED') return null;

  switch (event.kind) {
    case 'capability_resolved':
      if (state.kind !== 'INITIALIZING') return null;
      return { kind: 'CAPABILITY_OK', backend: event.backend };
    case 'capability_failed':
      if (state.kind !== 'INITIALIZING') return null;
      return { kind: 'CAPABILITY_FAILED', reason: event.reason };
    case 'load_started':
      if (state.kind !== 'CAPABILITY_OK' && state.kind !== 'READY' && state.kind !== 'NAVIGATING') {
        return null;
      }
      return { kind: 'LOADING_PANORAMA', sceneId: event.sceneId, progress01: 0 };
    case 'load_progress':
      if (state.kind !== 'LOADING_PANORAMA' || state.sceneId !== event.sceneId) return null;
      return { kind: 'LOADING_PANORAMA', sceneId: event.sceneId, progress01: event.progress01 };
    case 'load_completed':
      if (state.kind !== 'LOADING_PANORAMA' || state.sceneId !== event.sceneId) return null;
      return { kind: 'READY', sceneId: event.sceneId };
    case 'navigation_started':
      if (state.kind !== 'READY') return null;
      return {
        kind: 'NAVIGATING',
        fromSceneId: event.fromSceneId,
        toSceneId: event.toSceneId,
        progress01: 0,
      };
    case 'navigation_progress':
      if (state.kind !== 'NAVIGATING' || state.toSceneId !== event.toSceneId) return null;
      return {
        kind: 'NAVIGATING',
        fromSceneId: event.fromSceneId,
        toSceneId: event.toSceneId,
        progress01: event.progress01,
      };
    case 'navigation_completed':
      if (state.kind !== 'NAVIGATING' || state.toSceneId !== event.sceneId) return null;
      return { kind: 'READY', sceneId: event.sceneId };
    default:
      return null;
  }
};
