/**
 * Visitor-mode interactions.
 *
 * The existing TwinRegistry assumes the writer is an operator with
 * `twins.write` scope — the audit-trail entries carry `source:'operator'`
 * + an `actorId`. For B2B2C tours we also want VISITORS (anonymous end
 * users) to interact with a curated subset of twins: tap the lamp to
 * toggle it on/off, tap the door to open it, tap the curtain to draw
 * it. This module sits in front of the registry and enforces:
 *
 *   1. **Kind allow-list** — visitors can only toggle the kinds the
 *      tenant has opted into via `TenantInteractionCapabilities`. A
 *      brand selling "AR for floor only" gets nothing here; a brand
 *      with `lights: true, doors: false` only sees lamps tappable.
 *
 *   2. **Action allow-list** — even within an enabled kind, visitors
 *      cannot perform privileged transitions (e.g. unlocking a door,
 *      changing thermostat setpoint). Visitors get a fixed toggle
 *      action per kind:
 *        - lamp:   on ↔ off
 *        - door:   open ↔ closed  (only if NOT locked)
 *        - shade:  position 0 ↔ 1
 *        - media-display: playing ↔ paused (keeps existing source)
 *        - window: maps to shade (open/close pane)
 *        - faucet: maps to media-display (on/off — water visualised as
 *          translucent cylinder by the renderer)
 *        - tv:     alias for media-display
 *
 *   3. **Audit source** — every visitor write lands in the audit log
 *      tagged `source:'system'` with `note:'visitor-toggle:<sessionId>'`
 *      so operators can review visitor interactions without confusing
 *      them with real IoT or human-operator writes.
 */

import { TwinRegistryError } from './registry';

import type { TwinRegistry } from './registry';
import type { TwinAuditEntry, TwinKind, TwinState } from './types';

/** Which twin kinds a tenant has enabled for visitor interaction. */
export interface TenantInteractionCapabilities {
  readonly lights: boolean;
  readonly doors: boolean;
  readonly curtains: boolean;
  readonly windows: boolean;
  readonly appliances: boolean;
  /** Global scene effects (day/night, weather). Independent of twin toggles. */
  readonly effects?: {
    readonly dayNight: boolean;
    readonly weather: boolean;
  };
}

export const ALL_INTERACTIONS_OFF: TenantInteractionCapabilities = {
  lights: false,
  doors: false,
  curtains: false,
  windows: false,
  appliances: false,
  effects: { dayNight: false, weather: false },
};

export const ALL_INTERACTIONS_ON: TenantInteractionCapabilities = {
  lights: true,
  doors: true,
  curtains: true,
  windows: true,
  appliances: true,
  effects: { dayNight: true, weather: true },
};

/** Visitor-interaction policy — maps twin kinds to capability flags. */
const KIND_TO_CAPABILITY: Partial<Record<TwinKind, keyof TenantInteractionCapabilities>> = {
  lamp: 'lights',
  door: 'doors',
  shade: 'curtains',
  'media-display': 'appliances',
};

export type VisitorAction = 'toggle';

export interface VisitorToggleArgs {
  readonly twinId: string;
  readonly sessionId: string;
  /** Inject `Date.now` for tests. */
  readonly nowMs?: () => number;
}

export type VisitorToggleResult =
  | { ok: true; audit: TwinAuditEntry; newState: TwinState }
  | {
      ok: false;
      reason: 'unknown-twin' | 'kind-not-toggleable' | 'capability-disabled' | 'locked';
    };

/**
 * Apply a visitor toggle. The visitor never sees the registry directly —
 * this is the only call surface for end-user interactions.
 */
export function visitorToggle(
  registry: TwinRegistry,
  caps: TenantInteractionCapabilities,
  args: VisitorToggleArgs,
): VisitorToggleResult {
  const twin = registry.get(args.twinId);
  if (!twin) return { ok: false, reason: 'unknown-twin' };

  const capabilityKey = KIND_TO_CAPABILITY[twin.state.kind];
  if (!capabilityKey) {
    // Kinds like thermostat / sensor-occupancy / sensor-co2 / turnstile
    // are NEVER visitor-toggleable regardless of capability flags.
    return { ok: false, reason: 'kind-not-toggleable' };
  }
  if (!caps[capabilityKey]) {
    return { ok: false, reason: 'capability-disabled' };
  }

  const nextState = computeToggle(twin.state);
  if (nextState === null) {
    // Currently only door-locked falls through here.
    return { ok: false, reason: 'locked' };
  }

  try {
    const audit = registry.apply({
      twinId: args.twinId,
      next: nextState,
      source: 'system',
      note: `visitor-toggle:${args.sessionId}`,
      atMs: args.nowMs?.() ?? Date.now(),
    });
    return { ok: true, audit, newState: nextState };
  } catch (err) {
    if (err instanceof TwinRegistryError && err.code === 'unknown-twin') {
      return { ok: false, reason: 'unknown-twin' };
    }
    throw err;
  }
}

/** Pure helper — given a current state, return the toggled next state. */
function computeToggle(current: TwinState): TwinState | null {
  switch (current.kind) {
    case 'lamp':
      return {
        kind: 'lamp',
        state: {
          on: !current.state.on,
          // Restore last brightness on toggle-on; default to 1.0 if unset.
          brightness: current.state.on ? current.state.brightness : (current.state.brightness ?? 1),
        },
      };
    case 'door':
      if (!current.state.open && current.state.locked) return null;
      return {
        kind: 'door',
        state: { open: !current.state.open, locked: current.state.locked },
      };
    case 'shade':
      // Snap to fully open / fully closed on toggle.
      return {
        kind: 'shade',
        state: { position: current.state.position >= 0.5 ? 0 : 1 },
      };
    case 'media-display':
      return {
        kind: 'media-display',
        state: { playing: !current.state.playing, source: current.state.source },
      };
    default:
      return null;
  }
}

/** Helper for the viewer — list every twin in a scene that the visitor
 *  can interact with under the current capability set. Useful for the
 *  hotspot overlay to know which chips to mark as `tappable`. */
export function visitorTappableTwinIds(
  registry: TwinRegistry,
  sceneId: string,
  caps: TenantInteractionCapabilities,
): readonly string[] {
  const out: string[] = [];
  for (const twin of registry.twinsForScene(sceneId)) {
    const capKey = KIND_TO_CAPABILITY[twin.state.kind];
    if (capKey && caps[capKey]) out.push(twin.id);
  }
  return out;
}
