/**
 * Real photo tour using CC0 panoramas from Poly Haven.
 *
 * Four indoor scenes downloaded to `/panoramas/*.jpg` at build time:
 *   - lounge        (wooden_lounge.jpg)      — living room / lounge
 *   - hotel         (hotel_room.jpg)         — bedroom with TV
 *   - workshop      (artist_workshop.jpg)    — workspace with windows + lamps
 *   - hospital      (hospital_room.jpg)      — clinical room with curtains
 *
 * All four are CC0 (public domain) — see Poly Haven's licence at
 * https://polyhaven.com/license. Bundled in `apps/viewer/public/panoramas/`.
 *
 * Each scene declares hotspots so the visitor can teleport between
 * rooms, plus an interactive twin set (lamp / TV / curtain / door)
 * the chip overlay renders. Toggle a chip → state flips → analytics
 * + visual feedback (chip colour) updates. For a full panorama swap
 * on toggle, ship a second photo + register it as a PanoramaSpec
 * variant (S46).
 */

import { buildSceneGraph, type SceneGraph, type SceneNode } from '@nova/viewer-core';

import type { Twin } from '@nova/digital-twin';

const LOUNGE = '/panoramas/wooden_lounge.jpg';
const HOTEL = '/panoramas/hotel_room.jpg';
const WORKSHOP = '/panoramas/artist_workshop.jpg';
const HOSPITAL = '/panoramas/hospital_room.jpg';

const lounge: SceneNode = {
  id: 'lounge',
  name: 'Living lounge',
  defaultPanoramaUrl: LOUNGE,
  defaultYawDeg: 0,
  defaultPitchDeg: 0,
  defaultFovDeg: 75,
  minimapAnchor: { x: 0.2, y: 0.5 },
  hotspots: [
    {
      id: 'lounge-to-hotel',
      toSceneId: 'hotel',
      yawDeg: 60,
      pitchDeg: -5,
      arriveYawDeg: 180,
      arrivePitchDeg: 0,
      kind: 'doorway',
      label: 'To the bedroom',
      transition: 'fade',
    },
    {
      id: 'lounge-to-workshop',
      toSceneId: 'workshop',
      yawDeg: -100,
      pitchDeg: -5,
      arriveYawDeg: 90,
      arrivePitchDeg: 0,
      kind: 'doorway',
      label: 'To the workshop',
      transition: 'fade',
    },
  ],
};

const hotel: SceneNode = {
  id: 'hotel',
  name: 'Bedroom',
  defaultPanoramaUrl: HOTEL,
  defaultYawDeg: 90,
  defaultPitchDeg: 0,
  defaultFovDeg: 75,
  minimapAnchor: { x: 0.5, y: 0.5 },
  hotspots: [
    {
      id: 'hotel-to-lounge',
      toSceneId: 'lounge',
      yawDeg: 180,
      pitchDeg: -5,
      kind: 'doorway',
      label: 'Back to lounge',
      transition: 'fade',
    },
    {
      id: 'hotel-to-hospital',
      toSceneId: 'hospital',
      yawDeg: -45,
      pitchDeg: -5,
      kind: 'doorway',
      label: 'To the clinic',
      transition: 'fade',
    },
  ],
};

const workshop: SceneNode = {
  id: 'workshop',
  name: 'Artist workshop',
  defaultPanoramaUrl: WORKSHOP,
  defaultYawDeg: 0,
  defaultPitchDeg: 0,
  defaultFovDeg: 75,
  minimapAnchor: { x: 0.2, y: 0.85 },
  hotspots: [
    {
      id: 'workshop-to-lounge',
      toSceneId: 'lounge',
      yawDeg: -90,
      pitchDeg: -5,
      kind: 'doorway',
      label: 'Back to lounge',
      transition: 'fade',
    },
  ],
};

const hospital: SceneNode = {
  id: 'hospital',
  name: 'Clinic room',
  defaultPanoramaUrl: HOSPITAL,
  defaultYawDeg: 0,
  defaultPitchDeg: 0,
  defaultFovDeg: 75,
  minimapAnchor: { x: 0.85, y: 0.5 },
  hotspots: [
    {
      id: 'hospital-to-hotel',
      toSceneId: 'hotel',
      yawDeg: 180,
      pitchDeg: -5,
      kind: 'doorway',
      label: 'Back to bedroom',
      transition: 'fade',
    },
  ],
};

export const REAL_TOUR_GRAPH: SceneGraph = buildSceneGraph({
  scenes: [lounge, hotel, workshop, hospital],
  rootSceneId: 'lounge',
  minimapViewBox: { widthPx: 200, heightPx: 200 },
});

