import {
  arrangePoiLabels,
  projectPoiToScreen,
  tabOrder,
  type CameraState,
  type PoiAnchor,
} from '@nova/viewer-core';

import {
  POI_CARD_RENDERERS,
  renderUnknownPoiCard,
  type PoiRenderContext,
} from './poi-card-renderers';
import { POI_TYPE_GLYPHS, POI_TYPE_LABELS, type ViewerPoi } from './poi-types';

/**
 * POI overlay manager. Lives above the WebGL canvas as an absolutely-
 * positioned DOM layer:
 *
 *   pins:  one `<button class="poi-pin">` per POI, positioned with
 *          `transform: translate()` so animation is GPU-cheap
 *   card:  one shared `<dialog>` opened when a pin is activated; the
 *          per-type renderer paints the body
 *   cluster: one `<button class="poi-cluster">` per cluster (e.g. "+3")
 *
 * The manager subscribes to camera changes (via `update()`) and re-projects
 * every POI; pins outside the camera frustum are hidden (display:none).
 *
 * A11y model:
 *   - pins are real `<button>` elements with `aria-label` from POI type +
 *     optional title; Tab walks them left-to-right then top-to-bottom
 *   - card is a real `<dialog>` with `role="dialog" aria-modal="true"`,
 *     `aria-labelledby` pointing at the card title heading
 *   - Esc closes the card and restores focus to the opener pin
 *   - clicking outside the card closes it (focus also restored)
 */

export interface PoiOverlayArgs {
  hostEl: HTMLElement;
  pois: readonly ViewerPoi[];
  initialCamera: CameraState;
  locale: string;
  isRtl: boolean;
  onCta?: (kind: string, payload: Record<string, unknown>) => void;
}

export interface PoiOverlayHandle {
  update(camera: CameraState): void;
  dispose(): void;
  /** Test-only: open the card for a specific POI id. */
  openPoi(poiId: string): void;
}

interface PinHandle {
  button: HTMLButtonElement;
  anchor: PoiAnchor;
  poi: ViewerPoi;
}

interface ClusterHandle {
  button: HTMLButtonElement;
}

const CLUSTER_RADIUS_PX = 64;

export const mountPoiOverlay = (args: PoiOverlayArgs): PoiOverlayHandle => {
  const layer = document.createElement('div');
  layer.className = 'poi-overlay';
  layer.setAttribute('data-testid', 'poi-overlay');
  layer.style.position = 'absolute';
  layer.style.inset = '0';
  layer.style.pointerEvents = 'none';
  args.hostEl.appendChild(layer);

  const card = createCard();
  card.dialog.setAttribute('data-testid', 'poi-card');
  layer.appendChild(card.dialog);

  let lastOpenerId: string | null = null;
  const renderContext: PoiRenderContext = {
    locale: args.locale,
    isRtl: args.isRtl,
    ...(args.onCta !== undefined && { onCta: args.onCta }),
  };

  const pins = new Map<string, PinHandle>();
  const clusters = new Map<string, ClusterHandle>();
  let currentCamera = args.initialCamera;

  for (const poi of args.pois) {
    const anchor: PoiAnchor = {
      id: poi.id,
      yaw: poi.position.yaw,
      pitch: poi.position.pitch,
      ...(poi.zIndex !== undefined && { zIndex: poi.zIndex }),
    };
    const pin = createPin(poi, () => openPoi(poi.id, /* focusFirst */ true));
    layer.appendChild(pin);
    pins.set(poi.id, { button: pin, anchor, poi });
  }

  const openPoi = (poiId: string, focusFirst: boolean): void => {
    const handle = pins.get(poiId);
    if (handle === undefined) return;
    const renderer = POI_CARD_RENDERERS[handle.poi.typeCode] ?? renderUnknownPoiCard;
    const body = renderer(handle.poi, renderContext);
    card.titleId.textContent = POI_TYPE_LABELS[handle.poi.typeCode] ?? 'Point of interest';
    card.content.replaceChildren(body);
    lastOpenerId = poiId;
    showCard(card.dialog, focusFirst);
  };

  const update = (camera: CameraState): void => {
    currentCamera = camera;
    const viewport = { widthPx: args.hostEl.clientWidth, heightPx: args.hostEl.clientHeight };
    const anchors: PoiAnchor[] = [];
    for (const { anchor } of pins.values()) anchors.push(anchor);
    const projected = anchors.map((a) => projectPoiToScreen(a, currentCamera, viewport));
    const arrangement = arrangePoiLabels(projected, anchors, CLUSTER_RADIUS_PX);

    const visibleIds = new Set(arrangement.primary.map((p) => p.id));
    const projectedById = new Map(arrangement.primary.map((p) => [p.id, p]));
    for (const [id, handle] of pins) {
      const proj = projectedById.get(id);
      if (proj === undefined) {
        handle.button.style.display = 'none';
        continue;
      }
      handle.button.style.display = '';
      handle.button.style.transform = `translate(${proj.screenX.toFixed(1)}px, ${proj.screenY.toFixed(1)}px) translate(-50%, -50%)`;
    }

    // Rebuild clusters
    for (const [, c] of clusters) c.button.remove();
    clusters.clear();
    for (const cluster of arrangement.clusters) {
      const primaryProj = projectedById.get(cluster.primaryId);
      if (primaryProj === undefined) continue;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'poi-cluster';
      btn.style.position = 'absolute';
      btn.style.transform = `translate(${(primaryProj.screenX + 28).toFixed(1)}px, ${(primaryProj.screenY - 28).toFixed(1)}px) translate(-50%, -50%)`;
      btn.style.pointerEvents = 'auto';
      btn.setAttribute('aria-label', `${cluster.count} more points of interest`);
      btn.textContent = `+${cluster.count - 1}`;
      btn.addEventListener('click', () => openPoi(cluster.primaryId, true));
      layer.appendChild(btn);
      clusters.set(cluster.primaryId, { button: btn });
    }

    // Update tab order: assign tabindex in left-to-right top-to-bottom order.
    const ordered = tabOrder(arrangement.primary.filter((p) => visibleIds.has(p.id)));
    ordered.forEach((id, idx) => {
      const handle = pins.get(id);
      if (handle === undefined) return;
      handle.button.tabIndex = idx === 0 ? 0 : 0;
      handle.button.setAttribute('data-tab-order', String(idx));
    });
  };

  // Initial paint
  update(currentCamera);

  const closeOnEscape = (event: KeyboardEvent): void => {
    if (event.key === 'Escape' && card.dialog.open) {
      event.preventDefault();
      hideCard(card.dialog);
      if (lastOpenerId !== null) {
        pins.get(lastOpenerId)?.button.focus();
      }
    }
  };
  card.closeBtn.addEventListener('click', () => {
    hideCard(card.dialog);
    if (lastOpenerId !== null) pins.get(lastOpenerId)?.button.focus();
  });
  card.dialog.addEventListener('click', (event) => {
    if (event.target === card.dialog) {
      hideCard(card.dialog);
      if (lastOpenerId !== null) pins.get(lastOpenerId)?.button.focus();
    }
  });
  document.addEventListener('keydown', closeOnEscape);

  return {
    update,
    openPoi(poiId): void {
      openPoi(poiId, true);
    },
    dispose(): void {
      document.removeEventListener('keydown', closeOnEscape);
      layer.remove();
      pins.clear();
      clusters.clear();
    },
  };
};

interface CardHandles {
  dialog: HTMLDialogElement;
  titleId: HTMLHeadingElement;
  content: HTMLDivElement;
  closeBtn: HTMLButtonElement;
}

const createCard = (): CardHandles => {
  const dialog = document.createElement('dialog');
  dialog.className = 'poi-card';
  dialog.setAttribute('aria-labelledby', 'poi-card-title');
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'poi-card-close';
  close.setAttribute('aria-label', 'Close');
  close.textContent = '×';
  const title = document.createElement('h2');
  title.id = 'poi-card-title';
  title.className = 'poi-card-shell-title';
  title.textContent = '';
  const content = document.createElement('div');
  content.className = 'poi-card-content';
  dialog.append(close, title, content);
  return { dialog, titleId: title, content, closeBtn: close };
};

const showCard = (dialog: HTMLDialogElement, focusFirst: boolean): void => {
  if (typeof dialog.showModal === 'function') {
    dialog.showModal();
  } else {
    dialog.setAttribute('open', '');
  }
  if (focusFirst) {
    const focusable = dialog.querySelector<HTMLElement>(
      'button, a, input, textarea, [tabindex="0"]',
    );
    focusable?.focus();
  }
};

const hideCard = (dialog: HTMLDialogElement): void => {
  if (typeof dialog.close === 'function') {
    dialog.close();
  } else {
    dialog.removeAttribute('open');
  }
};

const createPin = (poi: ViewerPoi, onActivate: () => void): HTMLButtonElement => {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = `poi-pin poi-pin--${poi.typeCode.toLowerCase()}`;
  btn.setAttribute('data-poi-id', poi.id);
  btn.setAttribute('data-poi-type', poi.typeCode);
  btn.setAttribute('aria-label', POI_TYPE_LABELS[poi.typeCode] ?? 'Point of interest');
  btn.setAttribute('aria-haspopup', 'dialog');
  btn.style.position = 'absolute';
  btn.style.pointerEvents = 'auto';
  btn.style.left = '0';
  btn.style.top = '0';
  btn.textContent = POI_TYPE_GLYPHS[poi.typeCode] ?? '·';
  btn.addEventListener('click', () => onActivate());
  btn.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onActivate();
    }
  });
  return btn;
};
