/**
 * Twin state FSM — applies kind-specific invariants on state writes.
 *
 *   lamp:        brightness must be 0..1
 *   door:        opening a locked door requires unlock first
 *   thermostat:  setpointC must be 10..32 °C, mode in fixed enum
 *   occupancy:   enteredCount + exitedCount are monotone (never decrease)
 *   co2:         ppm must be ≥ 0
 *   turnstile:   counts monotone
 *   media-display: source non-empty when playing
 *   shade:       position 0..1
 *
 * Invalid writes throw `TwinStateError`. The registry captures the error
 * + leaves the twin unchanged so the dashboard can surface it.
 */

import type { LampState, ShadeState, TwinKind, TwinState } from './types';

export class TwinStateError extends Error {
  constructor(
    public readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = 'TwinStateError';
  }
}

/** Verify + (optionally) normalise an outgoing state write. */
export function validateTwinState(kind: TwinKind, state: TwinState): TwinState {
  if (state.kind !== kind) {
    throw new TwinStateError('kind-mismatch', `cannot apply ${state.kind} state to a ${kind} twin`);
  }
  switch (state.kind) {
    case 'lamp':
      return { kind: 'lamp', state: normaliseLamp(state.state) };
    case 'door':
      return state; // booleans only — already valid
    case 'thermostat':
      validateRange('setpointC', state.state.setpointC, 10, 32);
      validateRange('temperatureC', state.state.temperatureC, -40, 60);
      return state;
    case 'sensor-occupancy':
      validateNonNegative('enteredCount', state.state.enteredCount);
      validateNonNegative('exitedCount', state.state.exitedCount);
      return state;
    case 'sensor-co2':
      validateNonNegative('ppm', state.state.ppm);
      return state;
    case 'turnstile':
      validateNonNegative('enteredCount', state.state.enteredCount);
      validateNonNegative('exitedCount', state.state.exitedCount);
      return state;
    case 'media-display':
      if (state.state.playing && state.state.source.length === 0) {
        throw new TwinStateError(
          'playing-without-source',
          'media-display cannot be playing without a source',
        );
      }
      return state;
    case 'shade':
      return { kind: 'shade', state: normaliseShade(state.state) };
  }
}

/** Apply an incremental transition + return the new state. */
export function transitionTwinState(before: TwinState, next: TwinState): TwinState {
  if (before.kind !== next.kind) {
    throw new TwinStateError('kind-mismatch', `cannot transition ${before.kind} → ${next.kind}`);
  }
  if (before.kind === 'door' && next.kind === 'door') {
    // Can't OPEN a locked door — must unlock first.
    if (next.state.open && before.state.locked) {
      throw new TwinStateError('open-while-locked', `cannot open door — currently locked`);
    }
  }
  if (before.kind === 'sensor-occupancy' && next.kind === 'sensor-occupancy') {
    if (
      next.state.enteredCount < before.state.enteredCount ||
      next.state.exitedCount < before.state.exitedCount
    ) {
      throw new TwinStateError(
        'counters-not-monotone',
        'occupancy counters must be monotone (cannot decrement)',
      );
    }
  }
  if (before.kind === 'turnstile' && next.kind === 'turnstile') {
    if (
      next.state.enteredCount < before.state.enteredCount ||
      next.state.exitedCount < before.state.exitedCount
    ) {
      throw new TwinStateError('counters-not-monotone', 'turnstile counters must be monotone');
    }
  }
  return validateTwinState(next.kind, next);
}

function normaliseLamp(state: LampState): LampState {
  const brightness = state.brightness ?? (state.on ? 1 : 0);
  if (brightness < 0 || brightness > 1) {
    throw new TwinStateError(
      'brightness-out-of-range',
      `lamp brightness must be 0..1, got ${brightness}`,
    );
  }
  return { on: state.on, brightness };
}

function normaliseShade(state: ShadeState): ShadeState {
  if (state.position < 0 || state.position > 1) {
    throw new TwinStateError(
      'position-out-of-range',
      `shade position must be 0..1, got ${state.position}`,
    );
  }
  return state;
}

function validateRange(name: string, value: number, min: number, max: number): void {
  if (value < min || value > max) {
    throw new TwinStateError('out-of-range', `${name} must be ${min}..${max}, got ${value}`);
  }
}

function validateNonNegative(name: string, value: number): void {
  if (value < 0) {
    throw new TwinStateError('negative-value', `${name} must be >= 0, got ${value}`);
  }
}
