/**
 * Adaptive HDR exposure (F-05 + SRS §9 — the "photographic, not gaming" bar).
 *
 * The renderer tone-maps HDR equirectangular panoramas through Three.js's
 * `ACESFilmicToneMapping` with a viewer-side exposure multiplier. The user
 * sees an exposure slider in the chrome (0.5..2.0); the auto path reads the
 * panorama's pre-computed luminance histogram (written by media-svc S12
 * `Panorama.hdrMetadata`) and picks an exposure that puts the histogram
 * peak at mid-grey.
 *
 * `meanLuminance` is normalised to [0, 1] where 0.18 is mid-grey reference.
 * The mapping is intentionally gentle — bright outdoor panoramas land near
 * exposure 1.0, dim interiors near 1.4. Clamped so we never over-pull a
 * dark scene into clipping.
 */

export interface HdrMetadata {
  /** Average linear luminance in [0,1]. media-svc produces this at tile time. */
  meanLuminance?: number;
  /** Optional p95 — used to detect HDR-burst scenes that need tone-curve compression. */
  p95Luminance?: number;
  /** Pre-applied tone curve, if any. `'srgb'` means the source already mapped. */
  toneCurve?: 'linear' | 'srgb' | 'aces';
}

export const MIN_EXPOSURE = 0.5;
export const MAX_EXPOSURE = 2.0;
export const REFERENCE_LUMINANCE = 0.18;

const clamp = (n: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, n));

/**
 * Pick an exposure multiplier from HDR metadata. Falls back to 1.0 (neutral)
 * when metadata is missing.
 */
export const pickAutoExposure = (meta: HdrMetadata | undefined): number => {
  if (meta?.meanLuminance === undefined) return 1.0;
  if (meta.toneCurve === 'srgb' || meta.toneCurve === 'aces') return 1.0;
  // Ratio of target / actual. 0.18 / 0.36 = 0.5 → dial DOWN (bright scene).
  // 0.18 / 0.09 = 2.0 → dial UP (dim scene). We attenuate ×0.7 so we never
  // overshoot a 2x boost on near-black input.
  const ratio = REFERENCE_LUMINANCE / Math.max(meta.meanLuminance, 0.01);
  const target = 1.0 + (ratio - 1.0) * 0.7;
  return clamp(target, MIN_EXPOSURE, MAX_EXPOSURE);
};

/**
 * Manual exposure adjustment. Caller passes a UI slider value in [0,1];
 * we map to [MIN_EXPOSURE, MAX_EXPOSURE]. The auto value is the centre
 * (slider value 0.5 = auto pick).
 */
export const applyManualExposure = (auto: number, sliderValue01: number): number => {
  const t = clamp(sliderValue01, 0, 1);
  if (t < 0.5) {
    // Pull DOWN toward MIN
    const f = t / 0.5;
    return clamp(MIN_EXPOSURE + (auto - MIN_EXPOSURE) * f, MIN_EXPOSURE, auto);
  }
  // Push UP toward MAX
  const f = (t - 0.5) / 0.5;
  return clamp(auto + (MAX_EXPOSURE - auto) * f, auto, MAX_EXPOSURE);
};
