/**
 * Pure camera math + input-event mapping (FR-TVS-RND-006 touch +
 * FR-TVS-RND-007 keyboard). The viewer app wires this to Three.js's
 * camera; tests run it in isolation against simulated input events.
 *
 * Conventions:
 *   - yaw: 0..360 (wrapped); +ve = look right
 *   - pitch: -89..+89 (clamped); +ve = look up
 *   - fov: 30..110 (clamped); pinch zoom mutates this
 *
 * Touch pan: 1 finger drag → yaw/pitch delta proportional to canvas pixels.
 * Pinch zoom: 2 finger spread → fov delta inversely proportional.
 * Keyboard pan: arrow keys → fixed-step yaw/pitch.
 */

export interface CameraState {
  yaw: number;
  pitch: number;
  fov: number;
}

export const DEFAULT_CAMERA: CameraState = { yaw: 0, pitch: 0, fov: 75 };
export const MIN_PITCH = -89;
export const MAX_PITCH = 89;
export const MIN_FOV = 30;
export const MAX_FOV = 110;

const clamp = (n: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, n));
const wrapYaw = (n: number): number => ((n % 360) + 360) % 360;

export interface DragApplyArgs {
  deltaPxX: number;
  deltaPxY: number;
  viewportWidthPx: number;
  viewportHeightPx: number;
}

export const applyDragPan = (state: CameraState, args: DragApplyArgs): CameraState => {
  // Convert pixel delta to angular delta. A full viewport-width drag = a full
  // 360° turn (so a single drag spins all the way around — the old 180°/width
  // made a 360° panorama feel like it only covered half). A full viewport-
  // height drag = 120° pitch for quick look up/down.
  //
  // Vertical convention: drag UP → look UP (camera-style). Reviewers found the
  // older grab-the-world vertical (drag down → look up) inverted and kept
  // getting stuck staring at the ceiling, so the pitch follows the finger:
  // dragging the pointer up tilts the view up.
  const yawDelta = (args.deltaPxX / Math.max(args.viewportWidthPx, 1)) * 360;
  const pitchDelta = (args.deltaPxY / Math.max(args.viewportHeightPx, 1)) * 120;
  return {
    yaw: wrapYaw(state.yaw - yawDelta),
    pitch: clamp(state.pitch - pitchDelta, MIN_PITCH, MAX_PITCH),
    fov: state.fov,
  };
};

export interface PinchApplyArgs {
  /** Previous distance between the two touch points, in pixels. */
  prevDistancePx: number;
  /** Current distance. */
  nextDistancePx: number;
}

export const applyPinchZoom = (state: CameraState, args: PinchApplyArgs): CameraState => {
  const ratio = args.nextDistancePx / Math.max(args.prevDistancePx, 1);
  // Larger pinch = zoom IN = smaller fov. Multiplicative + clamped.
  const nextFov = clamp(state.fov / ratio, MIN_FOV, MAX_FOV);
  return { ...state, fov: nextFov };
};

const KEY_PAN_STEP_DEG = 6; // matches the chrome's a11y hint
const KEY_ZOOM_STEP_DEG = 4;

export type KeyboardCommand =
  | 'pan-left'
  | 'pan-right'
  | 'pan-up'
  | 'pan-down'
  | 'zoom-in'
  | 'zoom-out'
  | 'reset';

export const mapKeyToCommand = (event: { key: string }): KeyboardCommand | null => {
  switch (event.key) {
    case 'ArrowLeft':
      return 'pan-left';
    case 'ArrowRight':
      return 'pan-right';
    case 'ArrowUp':
      return 'pan-up';
    case 'ArrowDown':
      return 'pan-down';
    case '+':
    case '=':
      return 'zoom-in';
    case '-':
    case '_':
      return 'zoom-out';
    case 'Home':
    case '0':
      return 'reset';
    default:
      return null;
  }
};

export const applyKeyboardCommand = (state: CameraState, command: KeyboardCommand): CameraState => {
  switch (command) {
    case 'pan-left':
      return { ...state, yaw: wrapYaw(state.yaw - KEY_PAN_STEP_DEG) };
    case 'pan-right':
      return { ...state, yaw: wrapYaw(state.yaw + KEY_PAN_STEP_DEG) };
    case 'pan-up':
      return { ...state, pitch: clamp(state.pitch + KEY_PAN_STEP_DEG, MIN_PITCH, MAX_PITCH) };
    case 'pan-down':
      return { ...state, pitch: clamp(state.pitch - KEY_PAN_STEP_DEG, MIN_PITCH, MAX_PITCH) };
    case 'zoom-in':
      return { ...state, fov: clamp(state.fov - KEY_ZOOM_STEP_DEG, MIN_FOV, MAX_FOV) };
    case 'zoom-out':
      return { ...state, fov: clamp(state.fov + KEY_ZOOM_STEP_DEG, MIN_FOV, MAX_FOV) };
    case 'reset':
      return { ...DEFAULT_CAMERA };
    default:
      return state;
  }
};

/**
 * Compass bearing label for the chrome — 0° = North, 90° = East. The
 * panorama's local yaw doesn't have a natural cardinal direction, but the
 * scene's `initialView.yaw` declares which direction is "front" (= north),
 * so the viewer applies the offset.
 */
export const compassLabel = (yaw: number, northOffset: number): string => {
  const adjusted = wrapYaw(yaw - northOffset);
  const cardinals = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  const bucket = Math.round(adjusted / 45) % 8;
  return cardinals[bucket] ?? 'N';
};
