/**
 * Seeded deterministic RNG (mulberry32).
 *
 * Why our own? Particle systems need to be reproducible for tests + the
 * dashboard preview. `Math.random()` is non-deterministic; `crypto`
 * subtle is overkill for visuals. Mulberry32 is ~5 lines of arithmetic
 * with good period (2³²) and uniformity for our use case.
 */

export class SeededRng {
  private state: number;

  constructor(seed: number) {
    // Avoid 0 — produces a degenerate stream.
    this.state = seed | 0 || 1;
  }

  /** Next float in [0, 1). */
  next(): number {
    let t = (this.state += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /** Next float in [min, max). */
  range(min: number, max: number): number {
    return min + this.next() * (max - min);
  }

  /** Random unit vector on the upper hemisphere (Y >= 0). */
  unitHemisphereUp(): [number, number, number] {
    const cosTheta = this.next();
    const sinTheta = Math.sqrt(1 - cosTheta * cosTheta);
    const phi = this.next() * Math.PI * 2;
    return [Math.cos(phi) * sinTheta, cosTheta, Math.sin(phi) * sinTheta];
  }

  /** Random unit vector on the full unit sphere. */
  unitSphere(): [number, number, number] {
    const z = this.range(-1, 1);
    const r = Math.sqrt(Math.max(0, 1 - z * z));
    const phi = this.next() * Math.PI * 2;
    return [Math.cos(phi) * r, z, Math.sin(phi) * r];
  }

  /** Pick a random integer in [0, n). */
  intN(n: number): number {
    return Math.floor(this.next() * n);
  }
}
