/**
 * TwinRegistry — central catalogue + audit-trail keeper for all twins.
 *
 * Operator dashboard reads `list()` for the control panel; viewer reads
 * `twinsForScene()` to know which scene objects to highlight; the
 * IoT bridge calls `apply()` when a new measurement arrives.
 *
 * State changes always go through `apply()` so the audit-trail captures
 * every write (FR-OPS-AUD-001 mandates trail for IoT operations).
 */

import { transitionTwinState } from './twin-state';

import type { Twin, TwinAuditEntry, TwinKind, TwinState } from './types';

export class TwinRegistryError extends Error {
  constructor(
    public readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = 'TwinRegistryError';
  }
}

export interface ApplyArgs {
  twinId: string;
  next: TwinState;
  source: 'iot' | 'operator' | 'system';
  actorId?: string;
  note?: string;
  /** Optional override for the audit timestamp — defaults to `Date.now()`. */
  atMs?: number;
}

export class TwinRegistry {
  private readonly twins = new Map<string, Twin>();
  private readonly audit: TwinAuditEntry[] = [];
  private readonly maxAuditEntries: number;

  constructor(opts: { maxAuditEntries?: number } = {}) {
    this.maxAuditEntries = opts.maxAuditEntries ?? 5000;
  }

  register(twin: Twin): void {
    if (this.twins.has(twin.id)) {
      throw new TwinRegistryError('duplicate-twin', `twin "${twin.id}" is already registered`);
    }
    this.twins.set(twin.id, twin);
  }

  unregister(id: string): void {
    this.twins.delete(id);
  }

  get(id: string): Twin | null {
    return this.twins.get(id) ?? null;
  }

  list(filter: { sceneId?: string; kind?: TwinKind } = {}): readonly Twin[] {
    let out = [...this.twins.values()];
    if (filter.sceneId) out = out.filter((t) => t.binding.sceneId === filter.sceneId);
    if (filter.kind) out = out.filter((t) => t.state.kind === filter.kind);
    return out;
  }

  twinsForScene(sceneId: string): readonly Twin[] {
    return this.list({ sceneId });
  }

  /**
   * Apply a state write — validates the transition, updates the twin,
   * and appends an audit entry. Returns the new audit entry.
   */
  apply(args: ApplyArgs): TwinAuditEntry {
    const existing = this.twins.get(args.twinId);
    if (!existing) {
      throw new TwinRegistryError('unknown-twin', `twin "${args.twinId}" is not registered`);
    }
    const before = existing.state;
    const after = transitionTwinState(before, args.next);
    this.twins.set(args.twinId, { ...existing, state: after });
    const entry: TwinAuditEntry = {
      twinId: args.twinId,
      atMs: args.atMs ?? Date.now(),
      source: args.source,
      ...(args.actorId !== undefined && { actorId: args.actorId }),
      ...(args.note !== undefined && { note: args.note }),
      before,
      after,
    };
    this.audit.push(entry);
    if (this.audit.length > this.maxAuditEntries) {
      this.audit.splice(0, this.audit.length - this.maxAuditEntries);
    }
    return entry;
  }

  /** Audit log (most recent last). */
  auditLog(filter: { twinId?: string; sinceMs?: number } = {}): readonly TwinAuditEntry[] {
    let out = this.audit;
    if (filter.twinId) out = out.filter((e) => e.twinId === filter.twinId);
    if (filter.sinceMs !== undefined) out = out.filter((e) => e.atMs >= (filter.sinceMs ?? 0));
    return [...out];
  }

  /** Clear the audit log (housekeeping). */
  clearAudit(): void {
    this.audit.length = 0;
  }
}
