import {
  applyDragPan,
  applyPinchZoom,
  pickAutoExposure,
  type CameraState,
  type LodTier,
  type RendererBackend,
} from '@nova/viewer-core';
import {
  ACESFilmicToneMapping,
  AdditiveBlending,
  Mesh,
  MeshBasicMaterial,
  PerspectiveCamera,
  Scene,
  SphereGeometry,
  SRGBColorSpace,
  TextureLoader,
  Vector2,
  WebGLRenderer,
  type Texture,
  type WebGLRendererParameters,
} from 'three';

/**
 * Three.js panorama renderer. Mounted by `main.ts` after capability detection.
 *
 * Pipeline:
 *   1. Create a `WebGLRenderer` (WebGPU support would land via Three's
 *      WebGPURenderer; deferred to S35 when the LOD streamer + splat
 *      renderer share the WebGPU code path).
 *   2. Inverted sphere mesh — equirectangular texture mapped to the
 *      inside. Camera sits at the centre.
 *   3. `TextureLoader` fetches the panorama URL; `onProgress` drives the
 *      loading-bar fill. `onLoad` marks first-tile + triggers `onFirstTile`.
 *   4. Input layer: pointer drag → `applyDragPan`; pointer-pinch (2 touches)
 *      → `applyPinchZoom`; both are pure functions from `@nova/viewer-core`.
 *   5. `requestAnimationFrame` loop renders + auto-applies the exposure
 *      curve from the panorama's HDR metadata (currently neutral 1.0).
 */

export interface PanoramaRendererArgs {
  mountEl: HTMLElement;
  backend: RendererBackend;
  initialCamera: CameraState;
  initialLod: LodTier;
  panoramaUrl: string;
  onCameraChange: (next: CameraState) => void;
  onLoadProgress: (progress01: number) => void;
  onFirstTile: () => void;
}

/** An additive light layer = one room's (or object's) isolated light
 *  contribution, baked on a black background. Composited additively over the
 *  base panorama so it can be toggled on/off like a real light switch. */
export interface PanoramaLayer {
  id: string;
  url: string;
}

export interface PanoramaRendererHandle {
  setCamera(next: CameraState): void;
  setPanorama(args: {
    url: string;
    /** When > 0, dissolve from the current panorama into the new one over this
     *  many ms (pro "step-through" feel) instead of a hard swap. Honoured only
     *  when the user hasn't asked for reduced motion. */
    crossfadeMs?: number;
    onLoadProgress?: (progress01: number) => void;
    onFirstTile?: () => void;
  }): Promise<void>;
  /** Replace the active additive light layers (clears any previous). All
   *  start visible (lights on). Returns once every layer texture is loaded. */
  setLayers(layers: readonly PanoramaLayer[]): Promise<void>;
  /** Toggle one layer's visibility (the light on/off). */
  setLayerVisible(id: string, visible: boolean): void;
  dispose(): void;
}

const SPHERE_RADIUS = 500;
const SPHERE_SEGMENTS_BY_LOD: Record<LodTier, number> = {
  '8k': 80,
  '4k': 60,
  '2k': 48,
  '1k': 32,
};

export const mountPanoramaRenderer = async (
  args: PanoramaRendererArgs,
): Promise<PanoramaRendererHandle> => {
  const rendererParams: WebGLRendererParameters = {
    antialias: true,
    alpha: false,
    powerPreference: 'high-performance',
    preserveDrawingBuffer: false,
  };
  const renderer = new WebGLRenderer(rendererParams);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = pickAutoExposure(undefined);
  renderer.outputColorSpace = SRGBColorSpace;
  resizeRendererToContainer(renderer, args.mountEl);
  args.mountEl.appendChild(renderer.domElement);
  renderer.domElement.setAttribute('role', 'img');
  renderer.domElement.setAttribute('aria-label', 'Panorama scene');
  renderer.domElement.tabIndex = 0;

  const scene = new Scene();
  const camera = new PerspectiveCamera(
    args.initialCamera.fov,
    args.mountEl.clientWidth / Math.max(args.mountEl.clientHeight, 1),
    0.1,
    SPHERE_RADIUS * 2,
  );

  const segments = SPHERE_SEGMENTS_BY_LOD[args.initialLod];
  const geometry = new SphereGeometry(SPHERE_RADIUS, segments, segments);
  geometry.scale(-1, 1, 1); // invert so we see the inside of the sphere

  let currentTexture = await loadPanoramaTexture({
    url: args.panoramaUrl,
    onProgress: args.onLoadProgress,
    onFirstByte: args.onFirstTile,
  });

  // Canonical Three.js equirectangular-panorama pattern: invert the
  // sphere via geometry.scale(-1,1,1) and keep MeshBasicMaterial on its
  // default FrontSide. The negative determinant of scale(-1,1,1) already
  // flips winding order so the inside surface is what gets rasterised —
  // adding side: BackSide on top would cancel that out and cull every
  // triangle, leaving only the renderer's clear color visible.
  const material = new MeshBasicMaterial({
    map: currentTexture,
    toneMapped: true,
  });
  const mesh = new Mesh(geometry, material);
  scene.add(mesh);

  // Additive light layers (room/object light contributions on black). Each
  // is a second inverted sphere sharing the base geometry, blended additively
  // and drawn after the base so toggling it on "adds the light".
  const layerLoader = new TextureLoader();
  const layerMeshes = new Map<string, Mesh>();

  // Crossfade state: while a dissolve runs, the base sphere keeps showing the
  // OLD panorama and a second sphere (the fade mesh) fades the NEW one in on
  // top. On completion the base adopts the new texture and the fade mesh is
  // torn down. Only one fade runs at a time — a new swap finalizes the prior.
  let activeFade: {
    mesh: Mesh;
    mat: MeshBasicMaterial;
    nextTex: Texture;
    prevTex: Texture;
  } | null = null;
  const finalizeFade = (): void => {
    if (!activeFade) return;
    const f = activeFade;
    activeFade = null;
    material.map = f.nextTex;
    material.needsUpdate = true;
    currentTexture = f.nextTex;
    scene.remove(f.mesh);
    f.mat.dispose();
    f.prevTex.dispose();
  };

  const clearLayers = (): void => {
    for (const m of layerMeshes.values()) {
      scene.remove(m);
      const mat = m.material as MeshBasicMaterial;
      mat.map?.dispose();
      mat.dispose();
    }
    layerMeshes.clear();
  };

  applyCameraOrientation(camera, args.initialCamera);

  const resizeObserver = new ResizeObserver(() => {
    resizeRendererToContainer(renderer, args.mountEl);
    camera.aspect = args.mountEl.clientWidth / Math.max(args.mountEl.clientHeight, 1);
    camera.updateProjectionMatrix();
  });
  resizeObserver.observe(args.mountEl);

  let currentCamera = { ...args.initialCamera };
  const updateCamera = (next: CameraState): void => {
    currentCamera = next;
    applyCameraOrientation(camera, next);
    args.onCameraChange(next);
  };

  // Pointer + touch input wiring.
  const drag = createDragInputBinder(
    renderer.domElement,
    () => currentCamera,
    (next) => updateCamera(next),
  );
  const pinch = createPinchInputBinder(
    renderer.domElement,
    () => currentCamera,
    (next) => updateCamera(next),
  );

  let stopped = false;
  const renderLoop = (): void => {
    if (stopped) return;
    renderer.render(scene, camera);
    requestAnimationFrame(renderLoop);
  };
  requestAnimationFrame(renderLoop);

  return {
    setCamera(next): void {
      // External callers (refreshCompass) drive the camera via setCamera.
      // We update Three's camera + currentCamera but skip `onCameraChange`
      // since the caller already owns the source-of-truth state.
      currentCamera = next;
      applyCameraOrientation(camera, next);
    },
    async setPanorama(swapArgs): Promise<void> {
      const onProgress = swapArgs.onLoadProgress ?? noop;
      const onFirstByte = swapArgs.onFirstTile ?? noop;
      const nextTex = await loadPanoramaTexture({
        url: swapArgs.url,
        onProgress,
        onFirstByte,
      });
      const previous = currentTexture;
      const crossfadeMs = swapArgs.crossfadeMs ?? 0;
      const reduceMotion =
        typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;

      if (crossfadeMs <= 0 || reduceMotion) {
        finalizeFade(); // settle any in-flight fade before a hard swap
        currentTexture = nextTex;
        material.map = nextTex;
        material.needsUpdate = true;
        previous.dispose();
        return;
      }

      // Settle any prior fade instantly, then dissolve the new panorama in.
      finalizeFade();
      const fadeMat = new MeshBasicMaterial({
        map: nextTex,
        transparent: true,
        opacity: 0,
        toneMapped: true,
        depthTest: false,
        depthWrite: false,
      });
      const fadeMesh = new Mesh(geometry, fadeMat);
      fadeMesh.renderOrder = 2; // above the base sphere (0) and light layers (1)
      scene.add(fadeMesh);
      activeFade = { mesh: fadeMesh, mat: fadeMat, nextTex, prevTex: previous };

      await new Promise<void>((resolve) => {
        const start = performance.now();
        const tick = (): void => {
          if (stopped || activeFade?.mesh !== fadeMesh) {
            resolve(); // disposed or superseded by a newer swap
            return;
          }
          const t = Math.min(1, (performance.now() - start) / crossfadeMs);
          fadeMat.opacity = t;
          if (t < 1) {
            requestAnimationFrame(tick);
          } else {
            finalizeFade();
            resolve();
          }
        };
        requestAnimationFrame(tick);
      });
    },
    async setLayers(layers): Promise<void> {
      clearLayers();
      await Promise.all(
        layers.map(
          (layer) =>
            new Promise<void>((resolve) => {
              layerLoader.load(
                layer.url,
                (tex) => {
                  tex.colorSpace = SRGBColorSpace;
                  const layerMat = new MeshBasicMaterial({
                    map: tex,
                    transparent: true,
                    blending: AdditiveBlending,
                    depthWrite: false,
                    depthTest: false,
                    toneMapped: false,
                  });
                  const layerMesh = new Mesh(geometry, layerMat);
                  layerMesh.renderOrder = 1; // after the base sphere
                  scene.add(layerMesh);
                  layerMeshes.set(layer.id, layerMesh);
                  resolve();
                },
                undefined,
                () => resolve(), // a missing layer just means that light can't toggle
              );
            }),
        ),
      );
    },
    setLayerVisible(id, visible): void {
      const m = layerMeshes.get(id);
      if (m) m.visible = visible;
    },
    dispose(): void {
      stopped = true;
      finalizeFade();
      drag.dispose();
      pinch.dispose();
      resizeObserver.disconnect();
      clearLayers();
      geometry.dispose();
      material.dispose();
      currentTexture.dispose();
      renderer.dispose();
      if (renderer.domElement.parentElement === args.mountEl) {
        args.mountEl.removeChild(renderer.domElement);
      }
    },
  };
};

const resizeRendererToContainer = (renderer: WebGLRenderer, mountEl: HTMLElement): void => {
  const w = Math.max(mountEl.clientWidth, 320);
  const h = Math.max(mountEl.clientHeight, 240);
  renderer.setSize(w, h, false);
};

const applyCameraOrientation = (camera: PerspectiveCamera, state: CameraState): void => {
  const yawRad = (state.yaw * Math.PI) / 180;
  const pitchRad = (state.pitch * Math.PI) / 180;
  const targetX = SPHERE_RADIUS * Math.sin(yawRad) * Math.cos(pitchRad);
  const targetY = SPHERE_RADIUS * Math.sin(pitchRad);
  const targetZ = SPHERE_RADIUS * Math.cos(yawRad) * Math.cos(pitchRad);
  camera.position.set(0, 0, 0);
  camera.lookAt(targetX, targetY, targetZ);
  if (camera.fov !== state.fov) {
    camera.fov = state.fov;
    camera.updateProjectionMatrix();
  }
};

const loadPanoramaTexture = (args: {
  url: string;
  onProgress: (progress01: number) => void;
  onFirstByte: () => void;
}): Promise<Texture> =>
  new Promise((resolve, reject) => {
    const loader = new TextureLoader();
    let firstByteSeen = false;
    loader.load(
      args.url,
      (tex) => {
        tex.colorSpace = SRGBColorSpace;
        args.onProgress(1);
        resolve(tex);
      },
      (event) => {
        if (!firstByteSeen) {
          firstByteSeen = true;
          args.onFirstByte();
        }
        if (event.lengthComputable && event.total > 0) {
          args.onProgress(event.loaded / event.total);
        }
      },
      (err) => reject(err instanceof Error ? err : new Error(String(err))),
    );
  });

// ----------------------------------------------------------------------------
// Input binders
// ----------------------------------------------------------------------------

const createDragInputBinder = (
  canvas: HTMLCanvasElement,
  read: () => CameraState,
  write: (next: CameraState) => void,
): { dispose(): void } => {
  let active = false;
  let lastX = 0;
  let lastY = 0;
  let activePointerId: number | null = null;

  const onDown = (event: PointerEvent): void => {
    if (event.pointerType === 'touch' && document.querySelectorAll('canvas:active').length > 1) {
      return; // pinch path owns multi-touch
    }
    active = true;
    activePointerId = event.pointerId;
    lastX = event.clientX;
    lastY = event.clientY;
    canvas.setPointerCapture(event.pointerId);
  };
  const onMove = (event: PointerEvent): void => {
    if (!active || event.pointerId !== activePointerId) return;
    const dx = event.clientX - lastX;
    const dy = event.clientY - lastY;
    lastX = event.clientX;
    lastY = event.clientY;
    write(
      applyDragPan(read(), {
        deltaPxX: dx,
        deltaPxY: dy,
        viewportWidthPx: canvas.clientWidth,
        viewportHeightPx: canvas.clientHeight,
      }),
    );
  };
  const onUp = (event: PointerEvent): void => {
    if (event.pointerId !== activePointerId) return;
    active = false;
    activePointerId = null;
    canvas.releasePointerCapture(event.pointerId);
  };

  canvas.addEventListener('pointerdown', onDown);
  canvas.addEventListener('pointermove', onMove);
  canvas.addEventListener('pointerup', onUp);
  canvas.addEventListener('pointercancel', onUp);

  return {
    dispose(): void {
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      canvas.removeEventListener('pointerup', onUp);
      canvas.removeEventListener('pointercancel', onUp);
    },
  };
};

const createPinchInputBinder = (
  canvas: HTMLCanvasElement,
  read: () => CameraState,
  write: (next: CameraState) => void,
): { dispose(): void } => {
  const touchPoints = new Map<number, Vector2>();

  const distance = (): number => {
    if (touchPoints.size < 2) return 0;
    const [a, b] = [...touchPoints.values()];
    return a!.distanceTo(b!);
  };

  let prevDist = 0;

  const onDown = (event: PointerEvent): void => {
    if (event.pointerType !== 'touch') return;
    touchPoints.set(event.pointerId, new Vector2(event.clientX, event.clientY));
    if (touchPoints.size === 2) prevDist = distance();
  };
  const onMove = (event: PointerEvent): void => {
    if (event.pointerType !== 'touch') return;
    const point = touchPoints.get(event.pointerId);
    if (point === undefined) return;
    point.set(event.clientX, event.clientY);
    if (touchPoints.size === 2 && prevDist > 0) {
      const next = distance();
      write(applyPinchZoom(read(), { prevDistancePx: prevDist, nextDistancePx: next }));
      prevDist = next;
    }
  };
  const onUp = (event: PointerEvent): void => {
    touchPoints.delete(event.pointerId);
    if (touchPoints.size < 2) prevDist = 0;
  };

  canvas.addEventListener('pointerdown', onDown);
  canvas.addEventListener('pointermove', onMove);
  canvas.addEventListener('pointerup', onUp);
  canvas.addEventListener('pointercancel', onUp);

  return {
    dispose(): void {
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      canvas.removeEventListener('pointerup', onUp);
      canvas.removeEventListener('pointercancel', onUp);
    },
  };
};

// Used as the default no-op when callers omit progress/first-tile hooks.
const noop = (..._args: unknown[]): void => {
  void _args;
};

export const __testExports = { applyCameraOrientation, SPHERE_RADIUS };
